		"frustration": typesafe.Score("How frustrated is the customer?", []any{
			"Calm", "Frustrated", "Very angry",
		}),
	},
})
if err != nil {
	panic(err)
}
department, ok := result.Answers.Get("department")
if ok {
	fmt.Println(department.Choice)
}
```

